// Hand-written (NOT autogenerated). Guards the fields that start with '_':
// flatc does not export their accessors, so tools/ulsdkbuild reads them
// through the Get_ wrappers.

package entity

import (
	"reflect"
	"testing"

	"github.com/urbanlogiq/ulsdk/types/id"
)

func TestGraphNodeUnderscoreFieldsRoundTrip(t *testing.T) {
	desc := "Main St and 1st Ave"
	want := &GraphNode{
		Description: &desc,
		EntityType:  3,
		Geom:        &Point{PointGeo: []float32{-123.1, 49.2}},
		Location:    &Point{PointGeo: []float32{-123.1, 49.2}},
		NodeId:      &id.GenericId{B: []byte{0x0a, 0x0b}},
		NodeType:    2,
		Stream:      &id.ObjectId{B: []byte{0x05, 0x00, 0x79, 0x31}},
		Uid:         42,
	}
	got, err := GraphNodeFromBytes(want.ToBytes())
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("graph node:\n got %#v\nwant %#v", got, want)
	}
}

func TestGraphEdgeUnderscoreFieldsRoundTrip(t *testing.T) {
	want := &GraphEdge{From: 7, Kind: 1, To: 9}
	got, err := GraphEdgeFromBytes(want.ToBytes())
	if err != nil {
		t.Fatal(err)
	}
	if *got != *want {
		t.Fatalf("graph edge = %+v, want %+v", *got, *want)
	}
}
